crypto_script:
// Dr.COM eportal（dr1003，encrypt=1）：密钥 = 本机 IP 逐字符异或，
// 各字段字符再与密钥异或后转两位十六进制（与门户页面 JS 同一算法）。
// 运营商后缀按 Dr.COM 惯例并入账号：方案里账号填 2023xxxx@cmcc / @unicom /
// @telecom / @xyw，校园网账号通常不填后缀（具体以学校门户要求为准）。
function xorHex(str, key) {
  var out = "";
  for (var i = 0; i < str.length; i++) {
    var x = str.charCodeAt(i) ^ key;
    out += (x < 16 ? "0" : "") + x.toString(16);
  }
  return out;
}
function transform(ctx) {
  var ip = ctx.local_ip || "";
  if (!ip) {
    throw new Error("无法获取本机 IP（ctx.local_ip 为空），请确认已连接校园网");
  }
  var key = 0;
  for (var i = 0; i < ip.length; i++) {
    key ^= ip.charCodeAt(i);
  }
  return {
    callback: xorHex("dr1003", key),
    login_method: xorHex("1", key),
    user_account: xorHex(",0," + (ctx.username || ""), key),
    user_password: xorHex(ctx.password || "", key),
    wlan_user_ip: xorHex(ip, key),
    wlan_user_ipv6: "",
    wlan_user_mac: "",
    wlan_ac_ip: "",
    wlan_ac_name: "",
    jsVersion: xorHex("4.2.1", key),
    terminal_type: xorHex("1", key),
    lang: xorHex("zh-cn", key),
    v: String(Math.floor(Math.random() * 9000) + 1000)
  };
}
